var MET={running:9.8,jogging:7.0,cycling:7.5,walking:3.5,swimming:6.0,yoga:2.5,hiit:8.0,weights:5.0,dancing:5.0,skating:7.0};
function burn(activity, weightKg, minutes){
  activity=String(activity||'').toLowerCase(); weightKg=+weightKg; minutes=+minutes;
  var met=MET[activity]; if(met==null) return {error:'未知活动（试试 running/jogging/cycling/walking/swimming/yoga/hiit/weights/dancing/skating）'};
  var kcal=Math.round(met*3.5*weightKg/200*minutes*10)/10;
  return {activity:activity, met:met, kcal:kcal}; }
var EXPORTS={burn:burn, MET:MET};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CalorieBurnForgePure = EXPORTS; }
